    "punkte_bonus": 10,
    "aufgabe": "Info: Eiscafé San Marco Eschborn\nSamstag 10:00–19:00\nSonntag 12:00–19:00\nAufgabe: Macht ein Gruppenfoto vor der Eisdiele\nBonus: Gruppenfoto mit Eis",
