    "aufgabe": "Info: Selbstgemachtes Eis aus hochwertigen Zutaten gibt es in der \"Eismanufaktur Soest\".\nAufgabe: Macht ein Foto vor der Eisdiele.\nBonus: gönnt euch eine Kugel Eis an diesem aufregenden Tag.",
